import { test } from 'node:test'
import assert from 'node:assert/strict'
import { mkdirSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { harness } from './host-harness.mjs'
import { Config } from '../lib/index.js'

// Catches showing the host autogenerated page in place of the bundle's custom card.
test('bundle owns its settings page instead of the host automatic presentation', t => {
  const h = harness(t)
  assert.equal(h.presentations.at(-1)?.auto, false)
})

// Catches accepting out-of-range/fractional config or a schema that cannot produce live refs.
test('Config validates integer percentages 1 through 99', () => {
  for (const field of ['below300KPercent', 'above800KPercent', 'otherPercent']) {
    const schema = Config.dict[field]
    for (const value of [1, 23, 99]) assert.equal(schema(value).get(), value)
    for (const value of [0, 100, 23.5, '23', Infinity]) assert.throws(() => schema(value))
  }
})

// Catches capacity fallback to recent request data or a profile derived from the session workspace.
test('missing, malformed, unknown and invalid capacities use the other tier', async t => {
  const h = harness(t, { profile: false, config: { otherPercent: 23 } })
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.23)
  h.writeProfile('invalid: [yaml')
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.23)
  for (const capacity of [0, -10, 200_000.5, '200000', null, Number.MAX_SAFE_INTEGER + 1]) {
    h.writeProfile([{ id: 'llm-pi-ai', config: { providers: { magpie: { models: [{ id: 'unknown/model', contextWindow: capacity }] } } } }])
    assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.23)
  }
  h.writeProfile('- id: llm-pi-ai\n  config:\n    providers:\n      magpie:\n        apiKey: !!js process.env.KEY\n        models:\n          - id: unknown/model\n            contextWindow: 200000\n')
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.8)
  h.writeProfile('- id: llm-pi-ai\n  config:\n    providers:\n      magpie:\n        models:\n          - id: unknown/model\n            contextWindow: !!js 200000\n')
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.23)
})

// Catches ignoring DSH_PROFILE when DSH_PROFILE_DIR is absent.
test('profile fallback uses DSH_HOME/profiles/DSH_PROFILE and an absent profile remains unknown', async t => {
  const h = harness(t, { profileEnv: false, models: [{ id: 'small', contextWindow: 200_000 }] })
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.8)
  delete process.env.DSH_PROFILE
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.5)
})

// Catches reading frozen agent options, or resolving only through an existing request header.
test('fresh sessions use the current host default and old sessions fall back to their request header', async t => {
  const h = harness(t, { models: [{ id: 'small', contextWindow: 200_000 }, { id: 'stale/model', contextWindow: 900_000 }] })
  h.context.sessionProjections.snapshot = () => ({ values: { modelSelection: { next: null, lastUsed: null } } })
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's2' })).json.value.ratio, 0.8)
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.3)
})

// Catches moving checks to config/model events or using a fixed ratio inside either compaction hook.
test('pre-step and turn-stopping use the latest effective threshold', async t => {
  const h = harness(t, { models: [{ id: 'small', contextWindow: 200_000 }, { id: 'large', contextWindow: 900_000 }] })
  h.usage(600_000, 1_000_000)
  assert.equal(await h.preStep(), 'continued')
  assert.equal(h.compactions.length, 0)
  h.select({ provider: 'magpie', model: 'large' })
  assert.equal(h.compactions.length, 0)
  await h.preStep()
  assert.equal(h.compactions.length, 1)
  await h.call('thresholds.set', { sessionId: 's1', ratio: 0.65 })
  await h.stop()
  assert.equal(h.compactions.length, 1)
  await h.call('thresholds.reset', { sessionId: 's1' })
  assert.equal(h.compactions.length, 1)
  await h.stop()
  assert.equal(h.compactions.length, 2)
})

// Catches copying live config once, rounding 23%, or compacting as a config side effect.
test('automatic defaults follow live config without writing an override or starting compaction', async t => {
  let small = 23
  const config = { below300KPercent: { get: () => small }, above800KPercent: { get: () => 1 }, otherPercent: { get: () => 99 } }
  const h = harness(t, { models: [{ id: 'vendor/small', contextWindow: 200_000 }, { id: 'vendor/large', contextWindow: 900_000 }], config })
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.23)
  small = 61
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.61)
  h.select({ provider: 'magpie', model: 'vendor/large' })
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.01)
  h.select({ provider: 'magpie', model: 'missing/model' })
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.99)
  assert.deepEqual((await h.call('thresholds.get')).json.value, {})
  assert.equal(h.compactions.length, 0)
})

// Catches rejecting a valid profile just because another plugin was inserted.
test('mixed profile arrays retain explicit capacity and ambiguous model patches fall back', async t => {
  const h = harness(t, { selection: { provider: 'magpie', model: 'vendor/large' } })
  const row = { id: 'llm-pi-ai', config: { providers: { magpie: { models: [{ id: 'vendor/large', contextWindow: 872_000 }] } } } }
  h.writeProfile([row, { insert: [{ id: 'unrelated-plugin', name: 'unrelated-plugin' }] }])
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.3)
  h.writeProfile([{ insert: [{ ...row, name: '@deepseek-ai/dsh-llm-pi-ai' }] }])
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.3)
  h.writeProfile([row, { insert: [row] }])
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.5)
  h.writeProfile([row, row])
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.5)
  h.writeProfile([{ insert: [row] }, row])
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.5)
  h.writeProfile([{ ...row, disabled: true }])
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.5)
})

// Catches requiring profile env vars: the GUI host exports neither, so the one
// profile whose manifest declares this plugin must identify the running profile.
test('without profile env the sole declaring profile locates capacity; ambiguity or none falls back', async t => {
  const h = harness(t, { models: [{ id: 'small', contextWindow: 200_000 }] })
  const previous = ['DSH_PROFILE_DIR', 'DSH_PROFILE'].map(key => [key, process.env[key]])
  delete process.env.DSH_PROFILE_DIR
  delete process.env.DSH_PROFILE
  t.after(() => { for (const [key, value] of previous) { if (value === undefined) delete process.env[key]; else process.env[key] = value } })
  const declare = (name, capacity) => {
    mkdirSync(join(h.home, 'profiles', name), { recursive: true })
    writeFileSync(join(h.home, 'profiles', name, 'package.json'), JSON.stringify({ dependencies: { 'dsh-auto-compact': 'link:/checkout' } }))
    writeFileSync(join(h.home, 'profiles', name, 'cordis.patch.yml'),
      `- id: llm-pi-ai\n  name: "@deepseek-ai/dsh-llm-pi-ai"\n  config:\n    providers:\n      magpie:\n        models:\n          - id: small\n            contextWindow: ${capacity}\n`)
  }
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.5)
  declare('launcher', 200_000)
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.8)
  declare('beta', 900_000)
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.5)
  process.env.DSH_PROFILE_DIR = h.profileDir
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.8)
})

// Catches using a stale contextPressure window, splitting model ids, or inclusive tier boundaries.
test('effective defaults use explicit profile capacity and exact provider/full model selection', async t => {
  const h = harness(t, { models: [
    { id: 'vendor/small', contextWindow: 299_999 },
    { id: 'vendor/low-boundary', contextWindow: 300_000 },
    { id: 'vendor/high-boundary', contextWindow: 800_000 },
    { id: 'vendor/large', contextWindow: 800_001 },
  ] })
  for (const [model, want] of [['vendor/small', 0.8], ['vendor/low-boundary', 0.5], ['vendor/high-boundary', 0.5], ['vendor/large', 0.3]]) {
    h.select({ provider: 'magpie', model })
    const response = await h.call('thresholds.resolve', { sessionId: 's1', provider: 'fake', model: 'fake' })
    assert.equal(response.status, 200)
    assert.equal(response.json.value.ratio, want, model)
    assert.equal(response.json.value.overridden, false)
    assert.ok(!JSON.stringify(response.json).includes('secret-not-for-client'))
  }
  h.select({ provider: 'other', model: 'vendor/small' })
  assert.equal((await h.call('thresholds.resolve', { sessionId: 's1' })).json.value.ratio, 0.5)
})
